// Fetches the live MITRE ATLAS framework and writes it into
// src/data/atlas-bundled.js so the app ships pre-loaded with the latest matrix.
// Run: node scripts/build-atlas-bundle.mjs
import { writeFileSync } from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';
import { fetchATLASFramework } from '../src/utils/api.js';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const OUT = path.resolve(__dirname, '..', 'src', 'data', 'atlas-bundled.js');

const { matrix, version } = await fetchATLASFramework();
if (!Array.isArray(matrix) || matrix.length === 0) {
  throw new Error('Fetched matrix is empty.');
}

const content = `// Auto-generated by scripts/build-atlas-bundle.mjs — do not edit by hand.
// Bundled copy of the MITRE ATLAS framework so the app ships pre-loaded.
//
// MITRE ATLAS (https://atlas.mitre.org/) is copyright The MITRE Corporation.
// The ATLAS data bundled here is derived from the mitre-atlas/atlas-data
// repository and is licensed under the Apache License 2.0. A copy of the
// Apache-2.0 notice is provided in THIRD_PARTY_NOTICES.md.
// GroundRumble is not affiliated with, endorsed by, or sponsored by MITRE.
export const BUNDLED_ATLAS_VERSION = ${JSON.stringify(version || 'unknown')};
export const BUNDLED_ATLAS_MATRIX = ${JSON.stringify(matrix, null, 1)};
`;

writeFileSync(OUT, content);
console.log('wrote', OUT, '| version', version, '| tactics', matrix.length);
